        scwin.initPageIndex();await scwin.searchList()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil00330.slc_pageSize_onchange' }); }
};

/**
 * @method
 * @name grd_docPageList_oncellclick
 * @description grd_docPageList 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_docPageList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_docPageList');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_docPageList */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; } /* 수동 전환 필요: fn_viewOtherForm (인자 미해석) · document.getElementById('${doc.acptNo}'+'_0_otherForm').style.display = 'none'; (EL 미해석) · fn_Disclsviewer( '${doc.acptNo}'No }','${doc.disclsObjRepIsuSrtCd }','${fn:replace(doc.comEngAbbrv, '\'', '\\'') }' ); (EL 미해석) · fn_goWrite( '${doc.acptNo}', '${doc.formCd}', '${doc.formVer}', '${doc.currFormVer}', '${doc.currEngFormVer}', '${doc.oldFormVerUseYn}', '${doc.langTpCd}', '${doc.formUpclssCd}' ,'${doc.rsnClssCd}','${doc.modOrgnDisclsAcptNo}','${doc.inqOrgnDisclsAcptNo}','${doc.engOrgnDisclsAcptNo}','${doc.modAddSeq}','${doc.applFormYn}' ,'${doc.ldMktTpCd }','${doc.disclsAcptTpCd}','${doc.subcomDisclsYn }','${doc.disclsObjCorpIsurCd }','${doc.disclsObjCorpIsurNm }','${doc.disclsObjCorpFssUnqNo }','${doc.disclsObjRepIsuSrtCd }','${fn:replace(doc.comEngAbbrv, '\'', '\\'') }' ); (EL 미해석) · fn_goWrite( '${doc.acptNo}', '${doc.formCd}', '${doc.formVer}', '${doc.currFormVer}', '${doc.currEngFormVer}', '${doc.oldFormVerUseYn}', '${doc.langTpCd}', '${doc.formUpclssCd}' ,'${doc.rsnClssCd}','${doc.modOrgnDisclsAcptNo}','${doc.inqOrgnDisclsAcptNo}','${doc.engOrgnDisclsAcptNo}','${doc.modAddSeq}','${doc.applFormYn}' ,'${doc.ldMktTpCd }','${doc.disclsAcptTpCd}','${doc.subcomDisclsYn }','${doc.disclsObjCorpIsurCd }','${doc.disclsObjCorpIsurNm }','${doc.disclsObjCorpFssUnqNo }','${doc.disclsObjRepIsuSrtCd }','${fn:replace(doc.comEngAbbrv, '\'', '\\'') }' ); (EL 미해석) · fn_register( '${doc.acptNo}', '${doc.formCd}', '${doc.formVer}', '${doc.currFormVer}', '${doc.currEngFormVer}', '${doc.oldFormVerUseYn}', '${doc.langTpCd}', '${doc.formUpclssCd}' ,'${doc.rsnClssCd}','${doc.modOrgnDisclsAcptNo}','${doc.inqOrgnDisclsAcptNo}','${doc.engOrgnDisclsAcptNo}','${doc.modAddSeq}','${doc.applFormYn}' ,'${doc.ldMktTpCd }','${doc.disclsAcptTpCd}','${doc.subcomDisclsYn }','${doc.disclsObjCorpIsurCd }','${doc.disclsObjCorpIsurNm }','${doc.disclsObjCorpFssUnqNo }','${doc.disclsObjRepIsuSrtCd }','${doc.formCdExmpt}',${doc.formVerExmpt},'${fn:replace(doc.comEngAbbrv, '\'', '\\'') }', '${doc.reqObjAcptDocNo}' ); (EL 미해석) */

    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_docPageList.oncellclick' });
    }
};

/**
 * @method
 * @name krxpage_pagenavigator_224_onclick
 * @description krxpage_pagenavigator_224 클릭 이벤트
 * @param {Number} index index
 * @returns {void}
 * @hidden N
 */
scwin.krxpage_pagenavigator_224_onclick = async function (index) { const pi = (index && typeof index === 'object') ? index.newSelectedIndex : index; try { $c.util.getComponent('dma_searchListReq').set('pageIndex', pi); } catch (e) { $c.exception.handleError(e, { notify: 'none', context: 'krxpage_pagenavigator_224.page' }); } await scwin.tx_fn_searchList(); };

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_documentWrite
 * @description document Write 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_documentWrite = async function () {
    const sbmOptions = {
        id: "tx_fn_documentWrite",
        method: "post",
        action: "/submission/disclosure.do?method=searchDisclosureDocument&reqObjDocAcpNo=",
        ref: "dma_documentWriteReq",
        target: "dlt_docPageList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_register
 * @description register 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_register = async function () {
    const sbmOptions = {
        id: "tx_fn_register",
        method: "post",
        action: "/submission/searchDisclosureForm.do",
        ref: "dma_registerReq",
        target: "dlt_docPageList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_searchList
 * @description search List 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_searchList = async function () {
    const sbmOptions = {
        id: "tx_fn_searchList",
        method: "post",
        action: "/submission/searchDisclosureDocument.do?method=searchChangeInqueryDocument",
        ref: "dma_searchListReq",
        target: "dlt_docPageList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    const rj = res && res.responseJSON;
    const tot = rj && (rj["total"] != null ? rj["total"] : (rj.body && rj.body["total"]));
    if (tot != null && tot !== "") {
        $c.util.getComponent("krxpage_pagenavigator_224").setCount(Math.ceil(Number(tot) / 10));
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name initPageIndex
 * @description init Page Index 처리
 * @returns {void}
 * @hidden N
 */
scwin.initPageIndex = function () {
    $c.util.getComponent('dma_documentWriteReq').set('pageIndex', "1");
};

/**
 * @method
 * @name grd_docPageList_fmt_formKorNm
 * @description grd doc Page List fmt form Kor Nm 처리
 * @param {*} data 데이터
 * @param {*} formattedData 포맷된 값
 * @param {*} r r
 * @param {*} c c
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_docPageList_fmt_formKorNm = async function (data, formattedData, r, c) {
    try {
        const dl = $c.util.getComponent("dlt_docPageList");
        const v = String(dl && dl.getCellData ? (dl.getCellData(r, "oldFormVerUseYn") ?? '') : '');
        if (v === 'Y') { return '<a href="javascript:void(0)"' + (true ? ' class="lnk"' : '') + '>' + String((dl && dl.getCellData ? dl.getCellData(r, "formKorNm") : '') ?? '') + '</a>'; }
        return '<a href="javascript:void(0)"' + (true ? ' class="lnk"' : '') + '>' + String((dl && dl.getCellData ? dl.getCellData(r, "formKorNm") : '') ?? '') + '</a>';
    } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: "grd_docPageList.formKorNm" }); return String(data ?? ''); }
};

/**
 * @method
 * @name grd_docPageList_fmt_column5
 * @description grd doc Page List fmt column5 처리
 * @param {*} data 데이터
 * @param {*} formattedData 포맷된 값
 * @param {*} r r
 * @param {*} c c
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_docPageList_fmt_column5 = async function (data, formattedData, r, c) {
    try {
        const dl = $c.util.getComponent("dlt_docPageList");
        const v = String(dl && dl.getCellData ? (dl.getCellData(r, "disclsAcptTpCd") ?? '') : '');
        if (v === 'F') { return "최초"; }
        if (v === 'M') { return "정정"; }
        if (v === 'A') { return "첨부추가"; }
        if (v === 'U') { return "첨부정정"; }
        return '';
    } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: "grd_docPageList.column5" }); return String(data ?? ''); }
};

/**
 * @method
 * @name grd_docPageList_fmt_column6
 * @description grd doc Page List fmt column6 처리
 * @param {*} data 데이터
 * @param {*} formattedData 포맷된 값
 * @param {*} r r
 * @param {*} c c
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_docPageList_fmt_column6 = async function (data, formattedData, r, c) {
    try {
        const dl = $c.util.getComponent("dlt_docPageList");
        const v = String(dl && dl.getCellData ? (dl.getCellData(r, "formUpclssCd") ?? '') : '');
        if (v === '09') { return "ELW"; }
        return '';
    } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: "grd_docPageList.column6" }); return String(data ?? ''); }
};

/**
 * @method
 * @name grd_docPageList_fmt_column7
 * @description grd doc Page List fmt column7 처리
 * @param {*} data 데이터
 * @param {*} formattedData 포맷된 값
 * @param {*} r r
 * @param {*} c c
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_docPageList_fmt_column7 = async function (data, formattedData, r, c) {
    try {
        const dl = $c.util.getComponent("dlt_docPageList");
        const v = String(dl && dl.getCellData ? (dl.getCellData(r, "listFormYn") ?? '') : '');
        if (v === 'Y') { return "상장"; }
        return '';
    } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: "grd_docPageList.column7" }); return String(data ?? ''); }
};

/**
 * @method
 * @name documentWrite
 * @description document Write 처리
 * @param {*} reqObjDocAcpNo reqObjDocAcpNo
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.documentWrite = async function (reqObjDocAcpNo) {
    (document.writeForm || { elements: [] }).action = '/submission/disclosure.do?method=searchDisclosureDocument&reqObjDocAcpNo=' + reqObjDocAcpNo;
    await scwin.tx_fn_documentWrite();
};

/**
 * @method
 * @name findCompany
 * @description find Company 처리
 * @returns {void}
 * @hidden N
 */
scwin.findCompany = function () {
    const corpSearchURL = '/jldfil00033/jldfil00033.xml?method=loadInitPage&ldMktTpCd=' + dma_disclosureVo.get("ldMktTpCd") + '';
    (Promise.resolve($c.win.openPopup(corpSearchURL, { id: "corpWin", scrollbars: false, resizable: false, width: "600", height: "570", type: "pageFramePopup" }, {})).then(function (r) { if (!r) return; let a = Array.isArray(r) ? r : [r]; if (a[0] && a[0].__sdd_rec) { const rec = a[0]; const nm = function (s) { return s.replace(/_/g, '').toLowerCase(); }; const ps = (String(scwin.setCorpInfo).match(/\(([^)]*)\)/) || ['', ''])[1].split(',').map(function (s) { return s.trim(); }).filter(Boolean); const nk = {}; for (let k in rec) nk[nm(k)] = rec[k]; a = ps.map(function (p) { return nk[nm(p)]; }); } try { scwin.setCorpInfo.apply(null, a); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'popup-recv' }); } }), { closed: false, focus: function () {}, close: function () { $c.win.getScope().closePopup("corpWin"); this.closed = true; } });
};

