 */
scwin.register = async function (acptNo, formCd, formVer, currFormVer, currEngFormVer, oldFormVerUseYn, langTpCd, formUpclssCd, rsnClssCd, modOrgnDisclsAcptNo, inqOrgnDisclsAcptNo, engOrgnDisclsAcptNo, modAddSeq, applFormYn, ldMktTpCd, disclsAcptTpCd, subcomDisclsYn, disclsObjCorpIsurCd, disclsObjCorpIsurNm, disclsObjCorpFssUnqNo, disclsObjRepIsuSrtCd, formCdExmpt, formVerExmpt, comEngAbbrv, reqObjAcptDocNo) {
